import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Archives","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/archives.md","filePath":"en/guide/archives.md"}'),r={name:"en/guide/archives.md"};function n(i,t,l,h,c,d){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="archives" tabindex="-1">Archives <a class="header-anchor" href="#archives" aria-label="Permalink to &quot;Archives&quot;">​</a></h1><p>The <strong>Archives</strong> page (<code>/archives</code>) gives access to the local copy of your mails, saved on the NAS in EML format. It stays available even when the mails were deleted from Gmail, and even when the Gmail account was disconnected.</p><p>Five tabs: <strong>Mails</strong>, <strong>Contacts</strong>, <strong>Trash</strong>, <strong>Retention</strong>, <strong>Shares</strong>.</p><hr><h2 id="header-and-backup" tabindex="-1">Header and backup <a class="header-anchor" href="#header-and-backup" aria-label="Permalink to &quot;Header and backup&quot;">​</a></h2><ul><li>Status: &quot;Last backup … ago · N mails&quot; (or &quot;No backup yet&quot;).</li><li><strong>Back up to the NAS now</strong>: saves the account&#39;s mails not archived yet; progress shows under the header and in <a href="./activity.html">Activity</a>.</li><li><strong>Export (.mbox)</strong>: downloads the account&#39;s archives as mbox (readable by Thunderbird or Apple Mail). When a search or filter is active, only the loaded results are exported.</li></ul><p>Other ways to fill the archives: <strong>Save to the NAS</strong> in <a href="./mails.html">Mail</a>, an account&#39;s <strong>Automatic backup</strong> in <a href="./settings.html#gmail-accounts">Settings › Gmail accounts</a>, rules &quot;Save to the NAS then delete&quot;, and the mbox / .eml / IMAP import in <a href="./settings.html#data">Settings › Data</a>.</p><hr><h2 id="mails-tab-search" tabindex="-1">Mails tab: search <a class="header-anchor" href="#mails-tab-search" aria-label="Permalink to &quot;Mails tab: search&quot;">​</a></h2><ul><li><strong>Label tree</strong> (on the left on desktop): <strong>All mails</strong> then the labels that hold archived mails, with their count. For an IMAP account, these are its folders (<strong>Folders</strong>).</li><li><strong>Full-text search</strong>: subject, sender, content and body, plus the text of PDF and Word (.docx) attachments, accent-insensitive, with <code>&quot;exact phrase&quot;</code>, <code>-excluded</code> and <code>OR</code>. Matching terms are highlighted in the extract; a mail found through an attachment shows &quot;Found in attachment “…”&quot; with that attachment&#39;s excerpt. Existing archives are indexed in the background after the update (shown in <a href="./activity.html">Activity</a>).</li><li><strong>Tags</strong> (below the labels on desktop): <strong>All tags</strong> then your tags, with their count. A selected tag filters the list and offers <strong>Delete tag &quot;…&quot;</strong>, which removes it from every archive of the account without deleting the mails.</li><li><strong>Filters</strong>: <strong>Sender</strong>, period (<strong>From</strong> / <strong>To</strong>), <strong>Min size (MB)</strong> / <strong>Max size (MB)</strong>, <strong>Attachment type</strong> (an extension such as <code>pdf</code> or <code>docx</code>, or a MIME type such as <code>image/</code> for every image), <strong>With attachment</strong>. On mobile they sit in the <strong>Filters (N)</strong> panel with the <strong>Label</strong> (the <strong>Folder</strong> for an IMAP account) and the <strong>Tag</strong>, then <strong>Show results</strong>.</li></ul><p>Results (&quot;N results&quot;) show <strong>Subject</strong>, <strong>Extract</strong>, <strong>Date</strong>, <strong>Sender</strong>, <strong>Size</strong>. <strong>Clear search and filters</strong> goes back to the full list.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ul><li>A row&#39;s <code>⋯</code> menu: <strong>Open</strong>, <strong>Share</strong>, <strong>Restore to mailbox</strong>, <strong>Delete</strong>.</li><li>Selecting several rows: <strong>Export .mbox</strong>, <strong>Tags</strong>, <strong>Restore to mailbox</strong>, <strong>Delete</strong>.</li></ul><p><strong>Tags</strong> adds or removes the typed tags (comma-separated, your existing tags are suggested) on the whole selection. Tags stay in Nid: Gmail never sees them, and they are kept when the mail is archived again.</p><p><strong>Delete</strong> moves the archives to the archive trash, with a toast &quot;Deleting N archives in 10 s&quot; and <strong>Undo</strong>.</p><h3 id="archive-reader" tabindex="-1">Archive reader <a class="header-anchor" href="#archive-reader" aria-label="Permalink to &quot;Archive reader&quot;">​</a></h3><p><strong>Open</strong> shows the archived mail: headers, body (remote images blocked, as in <a href="./mails.html#read-a-mail">Mail</a>), downloadable attachments, its <strong>Tags</strong> (remove one with a click, add some with the <strong>Add a tag…</strong> field then Enter) and <strong>Conversation</strong>. Actions: <strong>Share</strong>, <strong>Restore to mailbox</strong>, <strong>Delete</strong>.</p><h3 id="restore-to-mailbox" tabindex="-1">Restore to mailbox <a class="header-anchor" href="#restore-to-mailbox" aria-label="Permalink to &quot;Restore to mailbox&quot;">​</a></h3><p>Puts archived mails back into the account&#39;s mailbox (Gmail or IMAP server), from their EML. The restore runs in the background (shown in <a href="./activity.html">Activity</a>) and a notification gives the result.</p><p><strong>Gmail account</strong>: same headers, same date, same labels.</p><ul><li>A mail <strong>still in Gmail</strong> is skipped; a mail <strong>in Gmail&#39;s trash</strong> is taken out of it.</li><li>System labels (Inbox, Unread, Important, categories…) are put back as they were. A label deleted since is recreated with the same name. Trash, Spam and Drafts are not put back.</li><li>After the restore, the archive points to the new Gmail mail: the next backup does not archive it a second time.</li><li>An <strong>encrypted</strong> archive cannot be restored (the passphrase is not kept): it counts as an error.</li><li>Not available for an account that must be reconnected.</li></ul><p><strong>IMAP account</strong>: the mail is uploaded, marked read and at its date, to the folder it was archived from if it still exists on the server, else to the inbox. A mail already in that folder (same Message-ID) is skipped. If the server refuses the password, the restore fails with that message and the account moves to <strong>Action required</strong>.</p><p>An encrypted archived mail shows &quot;This mail is encrypted: its content cannot be read here.&quot; Archive encryption was removed from Nid: put these archives back in clear in <a href="./settings.html#encrypted-archives">Settings › Data</a>.</p><hr><h2 id="share-a-mail" tabindex="-1">Share a mail <a class="header-anchor" href="#share-a-mail" aria-label="Permalink to &quot;Share a mail&quot;">​</a></h2><p><strong>Share</strong> opens &quot;Share this mail&quot;: a temporary link, readable without a Nid account.</p><ol><li>Pick how long it is <strong>Valid for</strong>: 1 hour, 24 hours, 3 days, 7 days or 30 days.</li><li><strong>Create link</strong>, then copy it.</li></ol><p>The window also lists the active links of that mail (&quot;Expires on …&quot;) with copy and revoke buttons.</p><p>Whoever opens the link sees the mail (&quot;Email shared via temporary link&quot;), remote images blocked. An expired or revoked link, or one that reached its access limit, shows &quot;Link not found&quot;.</p><h3 id="shares-tab" tabindex="-1">Shares tab <a class="header-anchor" href="#shares-tab" aria-label="Permalink to &quot;Shares tab&quot;">​</a></h3><p>All your active links: <strong>Subject</strong>, <strong>Sender</strong>, <strong>Expires on</strong>, <strong>Accesses</strong> (opens / limit), copy, revoke. The number of active links is also shown in <a href="./settings.html#security">Settings › Security</a>.</p><hr><h2 id="contacts-tab" tabindex="-1">Contacts tab <a class="header-anchor" href="#contacts-tab" aria-label="Permalink to &quot;Contacts tab&quot;">​</a></h2><p>The archive&#39;s address book, taken from the <strong>From</strong> and <strong>To</strong> headers of archived mails (trash excluded). Your own address is left out.</p><ul><li>Each contact shows its <strong>name</strong> (one of the names seen in its mails), its <strong>address</strong>, how many archived mails have it <strong>As sender</strong> and <strong>As recipient</strong> (To field, possibly with other recipients) and the <strong>Last exchange</strong> date.</li><li>The contacts you exchange with most come first; <strong>Search contacts</strong> filters by name or address.</li><li>Clicking a contact opens the <strong>Mails</strong> tab filtered on that sender.</li></ul><p>Only the <strong>To</strong> field is read: Cc recipients do not appear.</p><hr><h2 id="trash-tab" tabindex="-1">Trash tab <a class="header-anchor" href="#trash-tab" aria-label="Permalink to &quot;Trash tab&quot;">​</a></h2><p>Deleted archives stay here before being erased from the NAS.</p><ul><li>&quot;N mails in the trash&quot;, with the <strong>Deleted on</strong> date.</li><li><strong>Restore</strong> one mail, or select several then <strong>Restore</strong>.</li><li><strong>Empty the trash</strong>: after confirmation, permanently deletes the mails and their attachments from the NAS. Cannot be undone.</li><li>Automatic purge: &quot;Mails in the trash are permanently deleted after N days&quot; (or &quot;Automatic trash purge is off.&quot;). Administrators set <strong>Automatic purge</strong> and <strong>Days before purge</strong> here for the whole instance (see also <a href="./admin.html#system">Admin › System</a>).</li></ul><hr><h2 id="retention-tab" tabindex="-1">Retention tab <a class="header-anchor" href="#retention-tab" aria-label="Permalink to &quot;Retention tab&quot;">​</a></h2><p>&quot;Deletes archives older than a given age, for one label or all.&quot;</p><ul><li><strong>New policy</strong>: <strong>Name</strong>, <strong>Label</strong> (or <strong>All labels</strong>), <strong>Delete after (days)</strong>.</li><li>The list shows <strong>Name</strong>, <strong>Label</strong>, <strong>Age</strong> (&quot;Older than N days&quot;) and <strong>Last run</strong> (with the number of archives deleted).</li><li><strong>Run now</strong> applies every policy.</li><li>A policy&#39;s menu: edit, delete (after confirmation; archives already deleted do not come back).</li></ul><p>With no policy, archives are kept with no time limit.</p>',45)])])}const u=e(r,[["render",n]]);export{m as __pageData,u as default};
